import io, re
lines = io.open('TEST_RECORD.md', encoding='utf-8').read().split('\n')
def unesc(ln):
    return len(re.findall(r'(?<!\\\\)\|', ln))
bad = []
tot = 0
for i, ln in enumerate(lines, 1):
    if ln.startswith('| TR-'):
        tot += 1
        if unesc(ln) != 7:
            bad.append((i, unesc(ln), ln[:70]))
print('TR 行总数 =', tot)
print('未转义竖线 != 7 的行 =', bad if bad else '无')
"

