cd /d/workspace/projects/CreamPuffRobot && python -c "
import json, io, math
d = json.load(io.open('config/config.json', encoding='utf-8'))
def find(o, key, path=''):
    if isinstance(o, dict):
        for k, v in o.items():
            if k == key: yield path + '/' + k, v
            yield from find(v, key, path + '/' + k)
    elif isinstance(o, list):
        for i, v in enumerate(o): yield from find(v, key, path + '[%d]' % i)
for p, v in find(d, 'Axis_J2'): print('Axis_J2 @', p, '=', v)
print('toolOffsetX =', d['tcpCalibration']['toolOffsetX'])
"
